from pathlib import Path
import runpy,pprint
R=Path('/Users/johnbrophy/tigertest-next20-frvtc/tools/next20/frvtc')
def load(name):return runpy.run_path(str(R/(name+'.py')))['ROWS']
def edit(rows,n,stem,choices,explanation=None,objective=None):
 r=list(rows[n-1]); k=r[2];opts=list(choices[1:]);opts.insert(k,choices[0]);r[0]=stem;r[1]=opts
 if explanation:r[3]=explanation
 if objective:r[4]=objective
 rows[n-1]=tuple(r)
def save(name,rows):
 (R/(name+'.py')).write_text('"""Original source-backed items; corrective design in revision-plan-v2.md."""\nROWS = '+pprint.pformat(rows,width=118,sort_dicts=False)+'\n')
r=load('t3p')
edit(r,1,"Quatre conducteurs transportent des voisins contre une participation limitée aux frais. Quel trajet répond aussi à la condition liée au motif personnel du conducteur pour relever du covoiturage ?",["Léa rejoint sa famille, même sans passager","Marc rejoint la gare uniquement pour y déposer Paul","Inès sort de chez elle à la demande de deux voisins","Yann fait un détour complet sans destination personnelle"],"Le covoiturage suppose un déplacement que le conducteur effectue pour son propre compte, en plus du partage des frais. Léa conserve ici un motif de trajet indépendant de la demande des passagers.")
edit(r,2,"Un conducteur rejoint son lieu de travail et partage uniquement les frais avec ses passagers. Le site qui les a mis en relation facture séparément 2 € à chaque passager. À qui cette somme peut-elle rémunérer une prestation sans modifier, à elle seule, la nature du trajet ?",["Au site pour son service de mise en relation","Au conducteur pour sa disponibilité professionnelle","Au conducteur pour le temps de prise en charge","Au conducteur pour une marge sur le transport"],"L3132-1 autorise une mise en relation à titre onéreux. Cela distingue la rémunération du site de celle du conducteur, dont le trajet reste personnel et limité au partage des frais.")
edit(r,3,"Une commune compare une ligne d'autobus à horaires fixes, des taxis, des VTC sur réservation et un service de motos avec chauffeur. Quel service relève du transport public collectif plutôt que du T3P ?",["La ligne desservant les arrêts à heures fixes","Les taxis prenant des clients à leur station","Les voitures réservées pour chaque déplacement","Les motos transportant un client sur commande"],"La ligne d'autobus est un service collectif. Les taxis, VTC et véhicules motorisés à deux ou trois roues avec chauffeur relèvent des transports publics particuliers de personnes.")
edit(r,4,"Un passant souhaite monter dans un VTC libre à un feu. Le chauffeur possède sa carte, sa voiture porte ses vignettes et son exploitant est inscrit. Quelle pièce, propre à cette course, manque pour établir le droit de le prendre en charge ?",["Un justificatif de réservation antérieure","L'attestation de RC professionnelle","Le certificat d'immatriculation du véhicule","La carte professionnelle du conducteur"],"Les documents professionnels permanents ne prouvent pas la réservation de cette course. Le VTC ne peut prendre en charge sur la voie publique un client qui n'a pas réservé préalablement.")
edit(r,5,"Une application propose quatre écrans à une personne qui n'a pas réservé. Lequel constitue la combinaison interdite pour un VTC circulant sur la voie publique ?",["Une carte situant une voiture marquée « libre »","Un devis donnant prix et mode de règlement","Une fiche indiquant places et bagages admis","Un annuaire présentant entreprise et coordonnées"],"Avant réservation, informer simultanément sur la localisation et la disponibilité d'un VTC sur la voie publique relève de l'interdiction de maraude électronique. Les autres écrans n'associent pas ces deux renseignements.")
edit(r,6,"Une conductrice prépare son poste avant le service. Elle range l'assurance et la carte grise dans la boîte à gants, et garde son permis sur elle. Quel autre document personnel doit être apposé de façon visible de l'extérieur pendant l'activité ?",["Sa carte professionnelle de conducteur VTC","Son attestation de formation continue","Son certificat d'aptitude médicale","Son reçu de renouvellement du permis"],"La carte professionnelle doit être apposée de manière visible de l'extérieur pendant l'activité. Les autres pièces répondent à des fonctions distinctes et ne remplacent pas cet affichage.")
edit(r,7,"Après avoir cessé définitivement de conduire des VTC, Nora conserve son entreprise pour une autre activité. Quelle pièce personnelle doit-elle restituer à l'administration ?",["La carte professionnelle encore valable","Le certificat d'immatriculation de sa voiture","Les factures de ses anciennes prestations","L'attestation de son dernier stage suivi"],"La cessation définitive de l'activité de conducteur entraîne la restitution de la carte professionnelle. Elle ne se confond pas avec la conservation des pièces du véhicule ou des archives de l'entreprise.")
edit(r,8,"Maya habite Lyon, a réussi ses épreuves à Dijon et sera salariée d'une société parisienne, avec des courses au départ de Grenoble. Quelle préfecture est compétente pour sa demande de carte professionnelle ?",["La préfecture du Rhône","La préfecture de la Côte-d'Or","La préfecture de Paris","La préfecture de l'Isère"],"La demande relève de la préfecture du département du domicile du conducteur : ici le Rhône. Le siège de l'employeur, le centre d'examen et le lieu des courses ne déterminent pas cette compétence.")
edit(r,9,"Un candidat a quatre rendez-vous : visite chez son médecin traitant non agréé, contrôle chez un médecin agréé par la préfecture, examen visuel chez l'ophtalmologue et visite de santé au travail. Lequel répond au contrôle médical réglementaire d'aptitude à la conduite VTC ?",["Le contrôle par le médecin préfectoral agréé","La consultation du médecin traitant habituel","Le contrôle ophtalmologique des lunettes","La visite de santé auprès de l'employeur"],"L'avis réglementaire d'aptitude est délivré à l'issue du contrôle réalisé par un médecin agréé. Les autres consultations peuvent être utiles, mais ne remplissent pas cette fonction à elles seules.")
edit(r,10,"Un chauffeur doit choisir une session de formation continue VTC. Toutes les offres annoncent quatorze heures de cours. Quelle pièce lui permet de vérifier la qualité réglementaire de l'organisme, au-delà de son existence commerciale ?",["Son agrément de centre de formation VTC","Son inscription au registre des entreprises","Son contrat avec une plateforme de réservation","Son attestation d'assurance professionnelle"],"Le centre doit être agréé pour dispenser la formation réglementaire. Son immatriculation, son assurance ou ses partenaires ne prouvent pas cet agrément.")
edit(r,12,"Un chauffeur compare les usages indiqués dans quatre contrats automobiles. Il va effectuer des courses VTC facturées, avec sa propre voiture. Quel usage doit apparaître dans la couverture retenue ?",["Transport de personnes à titre onéreux","Déplacements privés et trajets domicile-travail","Mise en location sans conducteur","Transport de marchandises pour compte propre"],"Le contrat doit couvrir l'usage réel du véhicule : transporter des voyageurs contre rémunération. Les autres usages décrivent des risques différents.")
edit(r,13,"Le dossier d'un exploitant contient une assurance automobile couvrant le transport payant, une garantie vol et une assistance mécanique. Quelle attestation doit-il encore ajouter pour justifier la responsabilité liée à ses prestations professionnelles ?",["L'attestation de responsabilité civile professionnelle","Le certificat de garantie de valeur d'achat","Le contrat de prévoyance du dirigeant","L'assurance des locaux de stationnement"],"L3120-4 impose de pouvoir justifier la RC professionnelle. Elle est distincte des garanties du véhicule, des locaux ou de la personne du dirigeant.")
edit(r,14,"Un dossier comporte un avis médical favorable, une carte grise conforme, une assurance adaptée et une condamnation définitive au bulletin n° 2 pour conduite malgré l'annulation du permis. Quel contrôle du dossier relève directement cette difficulté ?",["Le contrôle de l'honorabilité du conducteur","La vérification de l'aptitude médicale","La vérification des garanties de l'exploitant","Le contrôle des caractéristiques du véhicule"],"Cette condamnation fait partie des obstacles à l'honorabilité professionnelle. Les autres contrôles sont nécessaires mais portent sur d'autres pièces et conditions.")
edit(r,15,"Un exploitant inscrit recrute Louis comme salarié. Louis fournit son permis adapté, son avis médical et son attestation de formation. Quelle autorisation personnelle doit aussi être vérifiée avant de lui confier les courses ?",["Sa carte professionnelle VTC","L'inscription REVTC de l'employeur","La licence de stationnement d'un taxi","L'immatriculation de sa propre entreprise"],"Le salarié doit posséder sa carte professionnelle. L'inscription de l'employeur autorise l'exploitation, sans se substituer à l'autorisation personnelle du conducteur ; Louis n'a pas à créer une entreprise.")
edit(r,16,"En novembre 2026, une première demande de carte est fondée uniquement sur une expérience de conduite en France. Aucun dossier n'était en cours avant la réforme et aucune qualification européenne n'est invoquée. Quel traitement correspond à cette situation ?",["Écarter la dispense nationale fondée sur cette expérience","Examiner le dossier sous le régime transitoire antérieur","Instruire une reconnaissance de qualification européenne","Renouveler une carte obtenue après réussite à l'examen"],"La réforme applicable depuis le 12 août 2026 a supprimé cette voie nationale pour les nouvelles demandes. Les autres traitements correspondent à des situations expressément absentes du dossier.")
edit(r,18,"Une plateforme examine quatre événements concernant un chauffeur : refus d'une proposition non acceptée, abandon d'une course acceptée, incident de conduite et absence à une prise en charge confirmée. Lequel relève expressément de la liberté de refus protégée par L1326-2 ?",["Le refus avant tout engagement sur la course","Le départ après acceptation de la réservation","L'incident survenu pendant le trajet réalisé","L'absence lors du rendez-vous déjà confirmé"],"La protection vise le refus d'une proposition, avant acceptation. Elle ne transforme pas un engagement accepté ou un incident pendant une prestation en simple refus de proposition.")
edit(r,19,"Un chauffeur indépendant souhaite conserver une clientèle personnelle. Parmi ces clauses, laquelle porte sur une restriction expressément interdite par L1326-4 ?",["Une clause interdisant de servir ses clients directs","Une clause précisant le calcul de la commission","Une clause décrivant les justificatifs de réservation","Une clause indiquant les moyens de joindre l'assistance"],"La plateforme ne peut interdire au conducteur de commercialiser lui-même ses services ni de recourir à plusieurs intermédiaires. Les autres objets contractuels ne constituent pas cette restriction.")
edit(r,20,"Le trajet proposé par une plateforme est encombré. Le client demande un autre itinéraire autorisé. Dans la répartition des rôles prévue pour le choix du parcours, qui prend la décision en tenant compte de cette demande ?",["Le conducteur qui réalise la prestation","Le service chargé des tarifs de la plateforme","Le centre de contrôle des réservations","L'exploitant de l'application de navigation"],"L1326-4 laisse le conducteur choisir son itinéraire en tenant compte de la demande du client. Le parcours suggéré par l'application n'est pas une instruction intangible.")
edit(r,22,"Quatre refus sont documentés. Lequel reste fondé sur un critère protégé même si l'appréciation du chauffeur était erronée ?",["Refuser une cliente pour une religion qu'on lui attribue","Refuser un groupe dépassant les places disponibles","Refuser des valises qui ne peuvent être arrimées","Refuser un créneau déjà engagé pour un autre client"],"La religion réelle ou supposée est un critère protégé. Une erreur sur la religion ne transforme pas ce motif en contrainte objective de capacité ou de disponibilité.")
edit(r,24,"Une cliente titulaire de la CMI invalidité, accompagnée de son chien guide, se voit refuser une course au titre de la politique « animaux interdits ». Quel document présenté par la cliente permet d'établir ici la qualité ouvrant le droit d'accès avec ce chien ?",["Sa carte mobilité inclusion portant la mention invalidité","La confirmation de réservation du transfert","Le reçu du paiement anticipé de la course","Son abonnement commercial auprès du transporteur"],"La CMI invalidité, dans la situation décrite avec un chien guide, relève des conditions légales du droit d'accès. La réservation, le paiement ou la fidélité commerciale ne remplacent pas cette qualité.")
edit(r,25,"Un devis accepté indique 38 € pour la course et 6 € pour un détour demandé à l'avance. Le chauffeur ajoute ensuite 8 € au seul motif que le client vient avec son chien guide, dans les conditions légales d'accès. Quel montant total résulte du retrait de la seule ligne interdite ?",["44 €","38 €","46 €","52 €"],"Le supplément de 8 € lié au chien guide est interdit. Le détour distinct et convenu n'est pas concerné par cette interdiction : 38 + 6 = 44 €.")
edit(r,26,"Après une rencontre, Camille accepte de donner son numéro de téléphone. Plus tard, Alex invoque cet accord pour justifier un geste sexuel qu'ils n'ont jamais évoqué. À quelle action l'accord établi dans ce récit se limitait-il ?",["À la transmission des coordonnées de Camille","Au rapprochement intime envisagé par Alex","À la poursuite physique de la rencontre","À la répétition ultérieure du geste envisagé"],"Le consentement est spécifique : accepter de transmettre ses coordonnées n'établit pas un accord pour un acte sexuel. Il faut apprécier l'accord relatif à cet acte lui-même.")
edit(r,27,"Au début d'un rapprochement, une personne exprime son accord. Quelques minutes plus tard, elle dit « je ne veux plus continuer ». Quel moment modifie la portée de l'accord initial pour la suite de l'interaction ?",["L'expression de son souhait d'arrêter","La décision initiale de se rencontrer","L'échange préalable de coordonnées","L'arrivée à l'endroit convenu ensemble"],"Le consentement est révocable. La demande d'arrêter retire l'accord pour la poursuite, même si la rencontre et son début avaient été acceptés.")
edit(r,28,"Une personne accepte un trajet, répond au chauffeur sur la destination, puis reste figée et silencieuse face à un geste sexuel. Quel élément reste à établir pour apprécier ce geste, sans le déduire de ses réponses précédentes ?",["Un accord libre et spécifique à l'acte sexuel","L'accord sur le lieu de dépose prévu","L'acceptation du déplacement professionnel","La compréhension de la destination annoncée"],"L'accord relatif au transport n'est pas un consentement à un acte sexuel. L'immobilité ou le silence ne permettent pas de déduire cet accord.")
edit(r,29,"Une conductrice décrit des remarques sexuelles humiliantes adressées par le même client lors de plusieurs trajets, malgré ses demandes d'arrêt. Quelle caractéristique du récit fonde ici la forme répétée du harcèlement sexuel ?",["Le retour des propos envers la même personne","Une pression isolée pour obtenir un acte sexuel","Un propos unique tenu par un groupe concerté","Un contact sexuel imposé pendant le trajet"],"Le récit décrit une répétition de propos à connotation sexuelle portant atteinte à la dignité. Les autres circonstances correspondent à des mécanismes différents et ne sont pas établies ici.")
edit(r,30,"Trois passagers ont préparé ensemble des remarques sexuelles humiliantes, puis chacun en adresse une à la même conductrice. Aucun ne renouvelle personnellement ses propos. Quel élément du dossier permet d'appliquer la règle du harcèlement concerté ?",["Les messages établissant leur préparation commune","Les relevés montrant des trajets différents","Le reçu identifiant le payeur de la course","La carte indiquant le domicile de la conductrice"],"La concertation entre plusieurs auteurs envers une même victime permet de retenir cette forme de harcèlement, même sans répétition individuelle. Les messages de préparation établissent ici cette concertation.")
edit(r,31,"Un responsable menace une conductrice de supprimer ses missions si elle refuse un acte sexuel. Il ne formule cette menace qu'une fois. Quel mécanisme juridique correspond à ces faits ?",["Une pression grave visant à obtenir un acte sexuel","Des propos sexuels renouvelés par un même auteur","Des remarques concertées entre plusieurs auteurs","Un acte sexuel imposé par un contact déjà réalisé"],"Une pression grave, même unique, visant réellement ou apparemment un acte sexuel est assimilée au harcèlement. Le récit ne décrit ni répétition, ni groupe concerté, ni contact réalisé.")
edit(r,33,"Une enquête établit un outrage sexiste commis par un passager dans un VTC. Le dossier contient le reçu, la trace du véhicule, le nom du réservataire et le tarif de nuit. Quelle pièce étaye le plus directement la circonstance aggravante liée au lieu des faits ?",["La trace situant les faits à bord du VTC","Le reçu indiquant le moyen de paiement","La réservation identifiant le donneur d'ordre","Le tarif indiquant une prestation nocturne"],"Le fait que l'outrage ait été commis à bord d'un VTC constitue la circonstance de lieu visée. Le règlement, le réservataire et le tarif nocturne n'établissent pas cette circonstance à eux seuls.")
edit(r,34,"Le service destinataire d'un signalement demande au chauffeur de compléter le récit des propos sexistes, déjà accompagné du reçu et de l'identité de l'exploitant. Quelle information répond directement à cette demande ?",["Les propos entendus, avec l'heure et le lieu","Le montant réglé et la référence du paiement","Le numéro REVTC et l'adresse du siège","La distance parcourue et le tarif kilométrique"],"Les mots entendus, le moment et le lieu décrivent les faits signalés. Les données de facturation et d'exploitation peuvent compléter le dossier, mais ne remplacent pas ce récit.")
edit(r,36,"Après son retour chez elle, une passagère majeure veut signaler des violences sexistes sans urgence immédiate. Elle souhaite d'abord un échange écrit avec les forces de l'ordre. Quel canal correspond à ce choix ?",["Le tchat officiel de signalement avec police ou gendarmerie","Le numéro 17 pour une intervention urgente","Le 3919 pour l'écoute et l'information","Le Défenseur des droits pour l'orientation juridique"],"Le tchat officiel permet cet échange écrit non urgent avec un policier ou un gendarme. Les autres canaux ont des missions ou modalités différentes ; le 17 vise une intervention urgente.")
save('t3p',r)
